def get(self, name, *args, **kwargs):
    ''' instantiates a plugin of the given name using arguments '''

    return self.get_with_context(name, *args, **kwargs).object

def get_with_context(self, name, *args, **kwargs):
    '''Instantiate a plugin and return it with its resolution context.'''

    found_in_cache = True
    class_only = kwargs.pop('class_only', False)
    collection_list = kwargs.pop('collection_list', None)
    if name in self.aliases:
        name = self.aliases[name]
    try:
        plugin_load_context = self.find_plugin_with_context(name, collection_list=collection_list)
    except AnsiblePluginError as exc:
        return get_with_context_result(None, exc.plugin_load_context)
    if not plugin_load_context.resolved or not plugin_load_context.plugin_resolved_path:
        # FIXME: this is probably an error (eg removed plugin)
        return get_with_context_result(None, plugin_load_context)

    name = plugin_load_context.plugin_resolved_name
    path = plugin_load_context.plugin_resolved_path
    redirected_names = plugin_load_context.redirect_list or []

    if path not in self._module_cache:
        self._module_cache[path] = self._load_module_source(name, path)
        self._load_config_defs(name, self._module_cache[path], path)
        found_in_cache = False

    obj = getattr(self._module_cache[path], self.class_name)
    if self.base_class:
        # The import path is hardcoded and should be the right place,
        # so we are not expecting an ImportError.
        module = __import__(self.package, fromlist=[self.base_class])
        # Check whether this obj has the required base class.
        try:
            plugin_class = getattr(module, self.base_class)
        except AttributeError:
            return get_with_context_result(None, plugin_load_context)
        if not issubclass(obj, plugin_class):
            return get_with_context_result(None, plugin_load_context)

    # FIXME: update this to use the load context
    self._display_plugin_load(self.class_name, name, self._searched_paths, path, found_in_cache=found_in_cache, class_only=class_only)

    if not class_only:
        try:
            # A plugin may need to use its _load_name in __init__ (for example, to set
            # or get options from config), so update the object before using the constructor
            instance = object.__new__(obj)
            self._update_object(instance, name, path, redirected_names)
            obj.__init__(instance, *args, **kwargs)
            obj = instance
        except TypeError as e:
            if "abstract" in e.args[0]:
                # Abstract Base Class.  The found plugin file does not
                # fully implement the defined interface.
                return None
            raise

    self._update_object(obj, name, path, redirected_names)
    return get_with_context_result(obj, plugin_load_context)

def _display_plugin_load(self, class_name, name, searched_paths, path, found_in_cache=None, class_only=None):
    ''' formats data to display debug info for plugin loading, also avoids processing unless really needed '''
    if C.DEFAULT_DEBUG:
        msg = 'Loading %s \'%s\' from %s' % (class_name, os.path.basename(name), path)

        if len(searched_paths) > 1:
            msg = '%s (searched paths: %s)' % (msg, self.format_paths(searched_paths))

    to_stderr = C.VERBOSE_TO_STDERR
    if self.verbosity > caplevel:
        if host is None:
            self.display(msg, color=C.COLOR_VERBOSE, stderr=to_stderr)
        else:
            self.display("<%s> %s" % (host, msg), color=C.COLOR_VERBOSE, stderr=to_stderr)

def get_deprecation_message(self, msg, version=None, date=None, removed=False, collection_name=None):
    """Format deprecation and removal messages consistently."""
    if removed:
        return "[DEPRECATED]: %s.\nPlease update your playbooks." % msg

    collection = collection_name
    if date and isinstance(date, string_types) and ':' in date and collection is None:
        collection, date = date.split(':', 1)
    if version and isinstance(version, string_types) and ':' in version and collection is None:
        collection, version = version.split(':', 1)
    if collection == 'ansible.builtin':
        collection = 'Ansible-base'
    if date:
        suffix = 'This feature will be removed in a release of %s after %s.' % (collection, date) if collection else 'This feature will be removed in a release after %s.' % date
    elif version:
        suffix = 'This feature will be removed in version %s of %s.' % (version, collection) if collection else 'This feature will be removed in version %s.' % version
    else:
        suffix = 'This feature will be removed in a future release%s.' % (' of ' + collection if collection else '')
    return '[DEPRECATION WARNING]: %s. %s Deprecation warnings can be disabled by setting deprecation_warnings=False in ansible.cfg.\n\n' % (msg, suffix)

